#include "../examples/windows_vehicle_app.hpp"
#include <SDL3/SDL.h>
#include <fstream>
#include <iostream>
using namespace engine;
namespace {
void require(bool value,const char* message){if(!value)throw std::runtime_error(message);}
Uint32 windowId(){int count=0;auto** windows=SDL_GetWindows(&count);require(windows&&count==1,"Expected one native window");const auto id=SDL_GetWindowID(windows[0]);SDL_free(windows);return id;}
void key(SDL_Scancode code,bool down=true){SDL_Event e{};e.type=down?SDL_EVENT_KEY_DOWN:SDL_EVENT_KEY_UP;e.key.windowID=windowId();e.key.scancode=code;e.key.key=SDL_GetKeyFromScancode(code,SDL_KMOD_NONE,false);e.key.down=down;require(SDL_PushEvent(&e),"Could not send native key");}
void click(GuiRect rect){for(auto type:{SDL_EVENT_MOUSE_BUTTON_DOWN,SDL_EVENT_MOUSE_BUTTON_UP}){SDL_Event e{};e.type=type;e.button.windowID=windowId();e.button.button=SDL_BUTTON_LEFT;e.button.x=rect.x+rect.width*.5f;e.button.y=rect.y+rect.height*.5f;e.button.down=type==SDL_EVENT_MOUSE_BUTTON_DOWN;require(SDL_PushEvent(&e),"Could not send native pointer");}}
void run(const std::filesystem::path& evidence,const std::filesystem::path& browserRecording){
    std::filesystem::create_directories(evidence);DesktopSettings settings;settings.hidden=true;DesktopHost host(settings);auto files=vehicle_example::vehicleFileSettings();files.userDirectory=evidence/"user";vehicle_example::VehicleDesktopDemo demo(host,{},files);double time=0;
    auto step=[&]{require(host.step(demo.callbacks(),time+=1./60),"Native host stopped early");require(host.captureError().empty(),"Native capture failed");};
    const auto started=host.nowSeconds();while(!host.diagnostics().ready){require(host.nowSeconds()-started<20,"Native GPU initialization timeout");step();SDL_Delay(2);}SDL_FlushEvents(SDL_EVENT_FIRST,SDL_EVENT_LAST);for(int i=0;i<10;++i)step();
    auto& replay=demo.replay();click(demo.recordButton().bounds());step();require(replay.recording(),"Record GUI did not start capture");key(SDL_SCANCODE_W);for(int i=0;i<95;++i)step();key(SDL_SCANCODE_W,false);key(SDL_SCANCODE_R);step();key(SDL_SCANCODE_R,false);step();key(SDL_SCANCODE_W);for(int i=0;i<90;++i)step();key(SDL_SCANCODE_W,false);step();replay.marker("Native brake/kerb marker");click(demo.finishRecordingButton().bounds());step();require(!replay.recording()&&replay.clip(),"Finish GUI did not publish recording");const auto recorded=replay.clip();require(recorded->duration()>2&&recorded->data().frames.size()>40,"Native driving samples missing");require(std::any_of(recorded->data().frames.begin(),recorded->data().frames.end(),[](const auto& f){return f.cut;}),"Reset cut was not recorded");require(std::any_of(recorded->data().events.begin(),recorded->data().events.end(),[](const auto& e){return e.name=="reset";}),"Reset event missing");
    demo.saveReplay(evidence/"native.weghost");const auto before=demo.vehicle().owner()->transform;const auto velocity=demo.vehicle().owner()->getComponent<RigidBodyComponent>()->linearVelocity();click(demo.reviewButton().bounds());step();require(replay.reviewing()&&host.application().state()==ApplicationState::Paused,"Review GUI did not pause live physics");auto scrub=demo.replayScrubber().bounds();scrub.width*=.6f;click(scrub);step();require(!replay.player()->playing()&&replay.player()->time()>0,"Native scrub did not pause/seek");const auto held=replay.player()->time();for(int i=0;i<30;++i)step();require(replay.player()->time()==held,"Paused replay advanced");require(demo.vehicle().owner()->transform.position.z==before.position.z,"Review changed live chassis pose");require(demo.vehicle().owner()->getComponent<RigidBodyComponent>()->linearVelocity().z==velocity.z,"Review changed live velocity");
    host.captureFrame(evidence/"review.ppm");for(int i=0;i<25;++i){step();SDL_Delay(2);}demo.closeReplay();step();require(!replay.reviewing(),"Close review failed");demo.loadReplay(evidence/"native.weghost");require(replay.clip()->duration()==recorded->duration(),"Native file roundtrip failed");
    bool crossPlatform=false;if(!browserRecording.empty()){demo.loadReplay(browserRecording);crossPlatform=true;require(replay.clip()->data().context==recorded->data().context,"Browser/native vehicle schema differs");}
    click(demo.raceGhostButton().bounds());step();require(replay.visible()&&!replay.reviewing()&&replay.player()->playing(),"Race GUI did not start ghost");auto& scene=*host.application().findScene(demo.sceneId());auto* ghost=scene.findActor(replay.ghostActor());require(ghost&&!ghost->getComponent<RigidBodyComponent>()&&!ghost->getComponent<VehicleComponent>(),"Ghost acquired physics components");for(int i=0;i<50;++i)step();require(replay.player()->time()>.2,"Ghost clock did not advance");host.setPaused(true);const auto paused=replay.player()->time();for(int i=0;i<15;++i)step();require(replay.player()->time()==paused,"Paused race advanced ghost");host.captureFrame(evidence/"ghost.ppm");for(int i=0;i<25;++i){step();SDL_Delay(2);}
    const auto good=replay.clip();const auto corrupt=evidence/"corrupt.weghost";{std::ofstream f(corrupt);f<<"WEGHOST 9 broken";}bool rejected=false;try{demo.loadReplay(corrupt);}catch(const std::exception&){rejected=true;}require(rejected&&replay.clip()==good,"Corrupt native load replaced good clip");demo.closeReplay();require(!replay.visible(),"Ghost not hidden after Close");
    std::ofstream report(evidence/"report.json");report<<"{\"passed\":true,\"nativeDawn\":true,\"browserFileAccepted\":"<<(crossPlatform?"true":"false")<<",\"duration\":"<<recorded->duration()<<",\"samples\":"<<recorded->data().frames.size()<<",\"events\":"<<recorded->data().events.size()<<",\"checks\":[\"GUI record/finish/review/race\",\"live physics frozen in review\",\"native slider scrubbing\",\"reset cut/event\",\"file roundtrip/corrupt retention\",\"render-only ghost\",\"paused clock\",\"Dawn framebuffer readback\"]}\n";
    host.requestClose();require(!host.step(demo.callbacks(),time+=1./60),"Host did not shut down");
}
}
int main(int argc,char** argv){try{run(argc>1?argv[1]:"build/evidence/replay-windows",argc>2?argv[2]:"");std::cout<<"Windows replay smoke passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
